def test_social_master_contract_channels_group_and_safety():
 d=json.loads((ROOT/'data/m248_social_friends_groups_chat_contract.json').read_text()); m=d['master_contract']; assert m['group_initial_target_size']==5 and m['group_size_final'] is False; assert set(['leader','invites','kick_leave','ready','target_pings','shared_objective_credit','personal_loot'])<=set(m['group_features']); assert set(['damage','effective_healing','shield_restore','cleanse','objectives'])<=set(m['contribution']); assert set(['overheal','afk_proximity'])<=set(m['excluded_contribution']); assert set(['world_global','region','map_optional','group','guild','alliance','whisper','system'])<=set(m['chat_channels']); assert set(['block','mute','report','rate_limits','spam_protection','server_moderation_logs'])<=set(d['safety_moderation']['requirements']); assert m['chat_gameplay_authority'] is False

def test_runtime_monotonic_readonly_social_replica():
 s=(ROOT/'scripts/progression/m248_social_runtime.gd').read_text();
 for token in ['class_name M248SocialRuntime','if incoming_revision < revision: return false','LOCAL_PREVIEW','func friend_rows()','func group_member_rows()','func chat_rows(channel: String = "")','func public_profile_rows()','func export_state()','func import_state(state: Dictionary)','can_client_authoritatively_add_friend() -> bool: return false','can_client_authoritatively_change_group() -> bool: return false','can_client_authoritatively_deliver_chat() -> bool: return false','can_client_authoritatively_block_or_mute() -> bool: return false','can_client_authoritatively_grant_group_credit() -> bool: return false']: assert token in s

def test_factory_save_ui_admin_wiring():
 f=(ROOT/'scripts/core/procedural_factory.gd').read_text(); gs=(ROOT/'scripts/core/game_state.gd').read_text(); ui=(ROOT/'scripts/ui/command_deck.gd').read_text(); reg=json.loads((ROOT/'data/admin_content_type_registry.json').read_text())['content_types']; assert 'M248SocialRuntime.new()' in f and 'social_runtime.name = "SocialRuntime"' in f; assert '"m248_social"' in gs and 'social_runtime.import_state' in gs; assert '"social"' in ui and 'SOZIALES · FREUNDE, GRUPPE & CHAT' in ui and 'M248SocialCatalog.chat_card' in ui; assert all(x in reg for x in ['friend_policy','group_policy','chat_channel_definition','report_definition'])

def test_convergence_promoted_partial_and_regressions_preserved():
 d=json.loads((ROOT/'data/m239_master_convergence_matrix.json').read_text()); by={x['domain']:x for x in d['domains']}; assert by['social_groups_chat_mail']['status']=='PARTIAL' and 'm248_fix' in by['social_groups_chat_mail']; assert ('mail/inbox service' in by['social_groups_chat_mail']['remaining'] or 'connected server mail/notification delivery service' in by['social_groups_chat_mail']['remaining']); hud=(ROOT/'scripts/ui/game_hud.gd').read_text(); assert 'no centered primary attack button' in hud and 'lower-right combat anchor' in hud; combat=(ROOT/'scripts/gameplay/enemy_ship_ai.gd').read_text(); assert 'canonical_attack_ready' in combat
